mapper.select:
select *
from schedule
where user_id = #{userId}
    and schedule_at between #{startDate} and #{endDate}

select *
from schedule
where schedule_id = #{scheduleId}
    and user_id = #{userId}

mapper.update:
update schedule
set schedule_name = #{scheduleName},
    category = #{category},
    schedule_at = #{scheduleAt}
where schedule_id = #{scheduleId}
    and user_id = #{userId}
